<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { inspectionExecutionLabel,inspectionCoverageText,inspectionFindings } from '../utils/inspection-status'
import { listManagedServers,type ManagedServer } from '../api/server-mgmt'
import { createInspection,deleteInspection,deleteInspectionPlan,downloadInspection,listInspectionPlans,listInspectionRuns,listOpsDatabases,saveInspectionPlan,type InspectionPlan,type InspectionRef,type InspectionRun,type OpsDatabase,type InspectionCommandOptions } from '../api/operations'
const route=useRoute(),router=useRouter(),tab=ref('runs'),runs=ref<InspectionRun[]>([]),plans=ref<InspectionPlan[]>([]),hosts=ref<ManagedServer[]>([]),databases=ref<OpsDatabase[]>([]),page=ref(1),total=ref(0),status=ref(''),error=ref(''),loading=ref(false),dialog=ref(false),saving=ref(false),mode=ref<'run'|'plan'>('run')
const form=reactive({id:0,name:'系统巡检报告',keys:[] as string[],services:'',enabled:true,dailyTime:'09:00',timezone:'Asia/Shanghai',commands:{} as Record<string,InspectionCommandOptions>})
const statusText=inspectionExecutionLabel
const statusType=(s:string)=>s==='COMPLETED'?'success':s==='FAILED'?'danger':['PARTIAL','UNKNOWN'].includes(s)?'warning':'info'
const time=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'-'
const options=computed(()=>[...hosts.value.map(h=>({key:`host:${h.id}`,label:`主机 · ${h.remark||h.host} · ${h.host}`})),...databases.value.map(d=>({key:`database:${d.id}`,label:`数据库 · ${d.name} · ${d.host}/${d.database}${d.serverId?'':'（未关联执行主机）'}`}))])
const commandProfiles=[{value:'kubernetes',label:'K8s 管理节点（1、7～10、13）'},{value:'k8s_host',label:'K8s 主机资源（6）'},{value:'deploy',label:'deploy 节点 Docker 镜像（14）'},{value:'node',label:'node 节点资源、日志与镜像（6、11、12、14）'},{value:'postgresql',label:'PostgreSQL 主机、Patroni 与归档（2、15～19）'},{value:'postgresql_archive',label:'归档目录及 Leader 核验（19）'},{value:'minio',label:'MinIO 主机及 mc 命令（3、36～39）'},{value:'postgres_backup',label:'PostgreSQL 备份服务器（4）'},{value:'minio_backup',label:'MinIO 备份服务器（5）'}]
const selectedObjects=computed(()=>options.value.filter(o=>form.keys.includes(o.key)))
function ensureCommands(){for(const key of form.keys){if(!form.commands[key])form.commands[key]={profiles:key.startsWith('database:')?['postgresql_sql']:[]}}}
const commandPayload=()=>Object.fromEntries(form.keys.map(key=>[key,form.commands[key]]))
const refs=()=>form.keys.map(key=>({type:key.split(':')[0],id:Number(key.split(':')[1])} as InspectionRef))
async function load(){if(loading.value)return;loading.value=true;try{if(tab.value==='runs'){const r=await listInspectionRuns(page.value,20,status.value);runs.value=r.list;total.value=r.total}else plans.value=await listInspectionPlans();error.value=''}catch(e:any){error.value=e.message}finally{loading.value=false}}
function open(kind:'run'|'plan',plan?:InspectionPlan){mode.value=kind;Object.assign(form,{id:plan?.id||0,name:plan?.name||(kind==='run'?'系统巡检报告':'每日巡检'),keys:plan?(JSON.parse(plan.targetsJSON)||[]).map((t:InspectionRef)=>`${t.type}:${t.id}`):[],services:plan?(JSON.parse(plan.servicesJSON)||[]).join(','):'',enabled:plan?.enabled??true,dailyTime:plan?.dailyTime||'09:00',timezone:plan?.timezone||'Asia/Shanghai',commands:plan?.commandsJSON?(JSON.parse(plan.commandsJSON)||{}):{}});if(!plan&&route.query.host)form.keys=[`host:${route.query.host}`];ensureCommands();dialog.value=true}
async function submit(){if(!form.keys.length){ElMessage.warning('请选择巡检对象');return};ensureCommands();if(form.keys.some(key=>!form.commands[key]?.profiles.length)){ElMessage.warning('请为每台服务器选择指导书对应的检查范围');return};saving.value=true;try{const services=form.services.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);if(mode.value==='run'){const r=await createInspection(form.name,refs(),services,commandPayload());dialog.value=false;router.push(`/inspections/${r.id}`)}else{await saveInspectionPlan({id:form.id||undefined,name:form.name,targets:refs(),services,enabled:form.enabled,dailyTime:form.dailyTime,timezone:form.timezone,commands:commandPayload()});dialog.value=false;await load();ElMessage.success('定时计划已保存')}}finally{saving.value=false}}
async function removeRun(row:InspectionRun){await ElMessageBox.confirm('删除此巡检及平台上的报告？此操作不修改被巡检服务器的业务数据。','删除巡检记录',{type:'warning'});await deleteInspection(row.id);await load()}
async function removePlan(row:InspectionPlan){await ElMessageBox.confirm('删除此定时计划？历史报告继续保留。','删除计划',{type:'warning'});await deleteInspectionPlan(row.id);await load()}
async function runPlan(row:InspectionPlan){const run=await createInspection(row.name,JSON.parse(row.targetsJSON),JSON.parse(row.servicesJSON)||[],row.commandsJSON?JSON.parse(row.commandsJSON):undefined);router.push(`/inspections/${run.id}`)}
async function report(id:number){try{await downloadInspection(id)}catch(e:any){ElMessage.error(e.message)}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{[hosts.value,databases.value]=await Promise.all([listManagedServers(),listOpsDatabases()]);await load();if(route.query.host)open('run');timer=setInterval(load,5000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><div class="inspections"><div class="heading"><div><h3>巡检报告</h3><p>用于客户环境节假日、季度等按需巡检，记录各组件运行情况并存档</p></div><div><el-button @click="open('plan')">新增定时计划</el-button><el-button type="primary" @click="open('run')">新建巡检报告</el-button></div></div><el-alert v-if="error" type="error" :title="error" :closable="false"/><div class="content"><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="巡检任务与报告" name="runs"/><el-tab-pane label="定时计划" name="plans"/></el-tabs>
<template v-if="tab==='runs'"><div class="filter"><el-select v-model="status" placeholder="全部状态" clearable style="width:160px" @change="page=1;load()"><el-option v-for="s in ['QUEUED','RUNNING','ENDED','FAILED','CANCELED','UNKNOWN']" :key="s" :value="s" :label="statusText(s)"/></el-select><el-button @click="load">刷新</el-button></div><el-table :data="runs" v-loading="loading" size="small"><el-table-column prop="id" label="#" width="65"/><el-table-column label="任务名称" min-width="200"><template #default="{row}"><el-link type="primary" @click="router.push(`/inspections/${row.id}`)">{{row.name}}</el-link></template></el-table-column><el-table-column label="任务执行" width="140"><template #default="{row}"><el-tag :type="statusType(row.status)" size="small">{{row.executionLabel||statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="已处理对象" width="110"><template #default="{row}">{{row.completedTargets}} / {{row.totalTargets}}</template></el-table-column><el-table-column label="检查结果与缺口" min-width="290"><template #default="{row}"><div>运行告警 {{inspectionFindings(row).warning}} · 严重问题 {{inspectionFindings(row).critical}}</div><el-link type="primary" @click="router.push(`/inspections/${row.id}`)">{{inspectionCoverageText(row)}}</el-link></template></el-table-column><el-table-column prop="operator" label="发起人" width="110"/><el-table-column label="创建时间" width="175"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column label="报告" width="200"><template #default="{row}"><el-button text size="small" :disabled="row.htmlStatus!=='READY'" @click="router.push(`/inspections/${row.id}/report`)">在线查看</el-button><el-button text size="small" :disabled="row.pdfStatus!=='READY'" @click="report(row.id)">下载 PDF</el-button><div v-if="row.pdfStatus==='FAILED'" class="report-error">PDF 生成失败，查看任务详情</div></template></el-table-column><el-table-column width="65"><template #default="{row}"><el-button v-if="!['QUEUED','RUNNING'].includes(row.status)" text type="danger" size="small" @click="removeRun(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></template>
<template v-else><el-table :data="plans" v-loading="loading" size="small"><el-table-column prop="name" label="计划名称" min-width="200"/><el-table-column label="启用" width="85"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="执行时间" width="200"><template #default="{row}">每天 {{row.dailyTime}} · {{row.timezone}}</template></el-table-column><el-table-column label="下次执行" min-width="180"><template #default="{row}">{{time(row.nextRunAt)}}</template></el-table-column><el-table-column prop="lastError" label="最近调度提示" min-width="180" show-overflow-tooltip/><el-table-column label="对象数量" width="100"><template #default="{row}">{{JSON.parse(row.targetsJSON)?.length||0}}</template></el-table-column><el-table-column width="220"><template #default="{row}"><el-button text type="primary" @click="runPlan(row)">立即执行</el-button><el-button text @click="open('plan',row)">编辑</el-button><el-button text type="danger" @click="removePlan(row)">删除</el-button></template></el-table-column></el-table></template></div>
<div class="templates"><div><strong>服务器命令检查</strong><p>按指导书执行对应服务器的 kubectl、patronictl、目录、df 和 mc 命令，记录原始结果。</p></div><div><strong>PostgreSQL 原 SQL</strong><p>执行指导书 20～35 的 16 条 SQL，包含表／索引膨胀 Top5；逐条保存查询返回与执行错误。</p></div></div>
<el-dialog v-model="dialog" :title="mode==='run'?'新建巡检报告':form.id?'编辑定时计划':'新增定时计划'" width="720px"><el-form label-width="110px"><el-form-item label="报告名称"><el-input v-model="form.name" maxlength="128"/></el-form-item><el-form-item label="巡检对象"><el-select v-model="form.keys" multiple filterable placeholder="选择主机和数据库，可混合选择" style="width:100%" @change="ensureCommands"><el-option v-for="o in options" :key="o.key" :value="o.key" :label="o.label"/></el-select></el-form-item><div v-for="obj in selectedObjects" :key="obj.key" class="command-object"><h4>{{obj.label}}</h4><template v-if="form.commands[obj.key]"><el-form-item v-if="obj.key.startsWith('host:')" label="执行范围"><el-select v-model="form.commands[obj.key].profiles" multiple placeholder="选择该服务器对应的指导书检查项" style="width:100%"><el-option v-for="profile in commandProfiles" :key="profile.value" :value="profile.value" :label="profile.label"/></el-select></el-form-item><p v-else>在关联服务器上使用已登记的数据库连接，执行指导书 20～35 的 16 条原 SQL。</p><template v-if="form.commands[obj.key].profiles.includes('kubernetes')"><el-form-item label="业务命名空间"><el-input v-model="form.commands[obj.key].namespace" placeholder="指导书为 prod，留空使用 prod"/></el-form-item><el-form-item label="Nacos Pod"><el-input v-model="form.commands[obj.key].nacosPod" placeholder="对应服务器 kubectl 可访问的 Pod 名称"/></el-form-item><el-form-item label="Nacos namespace"><el-input v-model="form.commands[obj.key].nacosNamespace" placeholder="留空使用 default"/></el-form-item><el-form-item label="Nacos 日志目录"><el-input v-model="form.commands[obj.key].nacosLogDirectory" placeholder="留空按指导书进入 logs；可填写实际绝对路径"/></el-form-item></template><el-form-item v-if="form.commands[obj.key].profiles.includes('node')" label="服务日志目录"><el-input v-model="form.commands[obj.key].logDirectory" placeholder="留空使用 /opt/logs/prod"/></el-form-item><el-form-item v-if="form.commands[obj.key].profiles.includes('postgresql')||form.commands[obj.key].profiles.includes('postgresql_archive')" label="Patroni 配置"><el-input v-model="form.commands[obj.key].patroniConfig" placeholder="可选，patronictl -c 使用的实际配置文件路径"/></el-form-item><el-form-item v-if="form.commands[obj.key].profiles.includes('postgresql')||form.commands[obj.key].profiles.includes('postgresql_archive')" label="归档目录"><el-input v-model="form.commands[obj.key].archiveDirectory" placeholder="实际归档目录；执行时自动核验本机是否为 Leader"/></el-form-item><el-form-item v-if="form.commands[obj.key].profiles.includes('minio')" label="已有 mc 别名"><el-input v-model="form.commands[obj.key].minioAlias" placeholder="该服务器已配置的 mc 别名"/></el-form-item><el-form-item v-if="form.commands[obj.key].profiles.includes('minio')" label="已有每日记录"><el-input v-model="form.commands[obj.key].minioDailyFile" placeholder="可选，客户已有零点采样记录文件的绝对路径"/><p>每行日期和 inode 已用数，如 2026-10-27 48697489。缺少记录时报告说明无法统计每日新增。</p></el-form-item><el-form-item v-if="form.commands[obj.key].profiles.includes('postgres_backup')" label="PG 备份目录"><el-input v-model="form.commands[obj.key].postgresBackupDirectory" placeholder="该备份服务器上的实际绝对路径"/></el-form-item><el-form-item v-if="form.commands[obj.key].profiles.includes('minio_backup')" label="MinIO 备份目录"><el-input v-model="form.commands[obj.key].minioBackupDirectory" placeholder="该备份服务器上的实际绝对路径"/></el-form-item></template></div><template v-if="mode==='plan'"><el-form-item label="每天执行时间"><el-time-select v-model="form.dailyTime" start="00:00" step="00:15" end="23:45"/></el-form-item><el-form-item label="时区"><el-input v-model="form.timezone"/></el-form-item><el-form-item label="启用计划"><el-switch v-model="form.enabled"/></el-form-item></template><el-alert title="使用对应服务器已有的 kubectl、patronictl、mc 等命令；数据库使用指导书原 SQL。报告保存标准输出、错误、时间和退出码，失败不会填成正常。" type="info" :closable="false"/></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">{{mode==='run'?'下发巡检任务':'保存计划'}}</el-button></template></el-dialog></div></template>
<style scoped>.command-object{border-top:1px solid #e2e8f0;padding-top:12px;margin:16px 0}.command-object h4{font-size:13px;line-height:1.6;margin:0 0 12px}.command-object p{font-size:12px;color:#65758b;line-height:1.7}.inspections{display:flex;flex-direction:column;gap:16px}.heading{display:flex;justify-content:space-between;align-items:center}.heading h3{margin:0}.heading p{font-size:12px;color:#78899c;margin-bottom:0}.content{padding:14px 18px;background:#fff;border:1px solid #e2e8f0;border-radius:8px}.filter{display:flex;gap:12px;margin-bottom:15px}.el-pagination{justify-content:flex-end;margin-top:15px}.templates{display:grid;grid-template-columns:1fr 1fr;gap:16px}.templates>div{padding:18px;background:#f6f8fc;border:1px solid #e2e8f0;border-radius:7px}.templates strong{font-size:13px;color:#354d6d}.templates p{font-size:12px;color:#718198;line-height:1.8;margin-bottom:0}@media(max-width:950px){.heading{align-items:flex-start;gap:12px;flex-direction:column}.templates{grid-template-columns:1fr}}</style>
